mapper.insert:
INSERT INTO order_item (
    order_id, product_id, product_name, quantity, price, amount, remark
) VALUES (
    #{orderId}, #{productId}, #{productName}, #{quantity}, #{price}, #{amount}, #{remark}
)

mapper.select:
SELECT COALESCE(SUM(i.quantity), 0)
FROM order_item i
INNER JOIN orders o ON i.order_id = o.id
WHERE i.product_id = #{productId}
  AND o.status IN ('PAID', 'PREPARING', 'SHIPPED', 'DELIVERED', 'COMPLETED')
  AND o.created_time >= #{startDate}
  AND o.created_time <= #{endDate}
